    AdmissionRejection SecondJudge(Recipe r, int a, IReadOnlyList<int> q)
    {
        if (skillLevels.QueryLevel(a, CraftSkillId) < r.SkillGate) return AdmissionRejection.SkillGate;
        if (q.Count == 0) return AdmissionRejection.NoConsumedInstances;
        int min = int.MaxValue;
        for (int i = 0; i < q.Count; i++) if (q[i] < min) min = q[i];
        if (min < r.MinQuality) return AdmissionRejection.MinQuality;
        return AdmissionRejection.None;
    }

    return IsAdmitted(SecondJudge(recipe, actorId, consumedQualities));
}

